import{D as e,f as t,j as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as s}from"./app-BE_K1prB.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S05/S05E16.html","title":"S05E16 The One with the Cop","lang":"zh-CN","frontmatter":{"title":"S05E16 The One with the Cop","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":113},"git":{"createdTime":1780654155000,"updatedTime":1785393428000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":2}]},"readingTime":{"minutes":36.49,"words":10947},"filePathRelative":"语言/英语/Friends老友记/S05/S05E16.md"}`),l={name:`S05E16.md`};function u(s,c,l,u,d,f){let p=n(`AudioButton`);return e(),o(`div`,null,[c[0]||=a(`h1`,{id:`the-one-with-the-cop`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#the-one-with-the-cop`},[a(`span`,null,`The One with the Cop`)])],-1),c[1]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`和警察在一起的那个`)])],-1),c[2]||=a(`p`,null,`The One With A Cop`,-1),c[3]||=a(`blockquote`,null,[a(`p`,null,`有警察的那个`)],-1),r(p,{src:`/audio/friends/S05/S05E16/001.mp3`}),c[4]||=i(),c[5]||=a(`strong`,null,`Story by:`,-1),c[6]||=i(` Alicia Sky Varinaitis`,-1),c[7]||=a(`blockquote`,null,[a(`p`,null,`Alicia Sky Varinaitis`)],-1),r(p,{src:`/audio/friends/S05/S05E16/002.mp3`}),c[8]||=t(` <strong>Teleplay by:</strong> Gigi McCreery &amp; Perry Rein<blockquote><p>吉吉·麦克里里和佩里·雷恩</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>Chandler and Joey&#39;s, Monica and Chandler are sitting on one of the chairs doing a crossword puzzle.</em></p><blockquote><p>🎬 <em>钱德勒和乔伊家，莫妮卡和钱德勒正坐在一把椅子上玩纵横填字游戏。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S05/S05E16/003.mp3`}),c[9]||=i(),c[10]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[11]||=i(` Hey!`,-1),c[12]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/004.mp3`}),c[13]||=i(),c[14]||=a(`strong`,null,`Chandler Bing:`,-1),c[15]||=i(` Hey!`,-1),c[16]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/005.mp3`}),c[17]||=i(),c[18]||=a(`strong`,null,`Monica Geller:`,-1),c[19]||=i(` Hey!`,-1),c[20]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/006.mp3`}),c[21]||=i(),c[22]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[23]||=i(` What are you guys doing up?`,-1),c[24]||=a(`blockquote`,null,[a(`p`,null,`你们在干什么？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/007.mp3`}),c[25]||=i(),c[26]||=a(`strong`,null,`Chandler Bing:`,-1),c[27]||=i(` Oh, we wanted to finish the crossword before we went to bed. Hey, do you know a six-letter word for red?`,-1),c[28]||=a(`blockquote`,null,[a(`p`,null,`哦，我们想在睡觉前完成纵横填字游戏。嘿，你知道红色的六个字母的词吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/008.mp3`}),c[29]||=i(),c[30]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[31]||=i(` (thinks) Dark red.`,-1),c[32]||=a(`blockquote`,null,[a(`p`,null,`（想）深红色。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/009.mp3`}),c[33]||=i(),c[34]||=a(`strong`,null,`Chandler Bing:`,-1),c[35]||=i(` Yeah, I think that's wrong, but there's a Connect the Dots in here for you later. (To Monica) Hey, how about maroon?`,-1),c[36]||=a(`blockquote`,null,[a(`p`,null,`是的，我认为这是错误的，但是这里有一个连接点，稍后给你。（对莫妮卡）嘿，栗色怎么样？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/010.mp3`}),c[37]||=i(),c[38]||=a(`strong`,null,`Monica Geller:`,-1),c[39]||=i(` (checks to see if it works) Yes, you are so smart! (Kisses him.)`,-1),c[40]||=a(`blockquote`,null,[a(`p`,null,`（检查它是否有效）是的，你真聪明！（吻他。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/011.mp3`}),c[41]||=i(),c[42]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[43]||=i(` Aww, you guys are so cute!`,-1),c[44]||=a(`blockquote`,null,[a(`p`,null,`哦，你们真可爱！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/012.mp3`}),c[45]||=i(),c[46]||=a(`strong`,null,`Monica Geller:`,-1),c[47]||=i(` I know.`,-1),c[48]||=a(`blockquote`,null,[a(`p`,null,`我知道。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/013.mp3`}),c[49]||=t(` <strong>Joey Tribbiani:</strong> All right, I&#39;ll see you in the morning.<blockquote><p>好吧，明天早上见。</p></blockquote><p>Chandler and **Monica Geller: **Okay.</p><blockquote><p>钱德勒和<strong>莫妮卡·盖勒：</strong>好的。</p></blockquote><hr><p>🎬 <em>Joey&#39;s bedroom, time lapse. He&#39;s asleep and dreaming. In his dream he&#39;s doing the crossword puzzle with…wait for it…Monica!</em></p><blockquote><p>🎬 <em>乔伊的卧室，时间流逝。他睡着了，在做梦。在梦中，他正在做纵横填字游戏，和…等等…莫妮卡！</em></p></blockquote><p>Dream **Monica Geller: **Y&#39;know, I love doing crossword puzzles with you honey!</p><blockquote><p>梦见<strong>莫妮卡·盖勒：</strong>你知道，我喜欢和你玩填字游戏，亲爱的！</p></blockquote><p>Dream **Joey Tribbiani: **Aww, me too. Now let&#39;s finish this and go to bed.</p><blockquote><p>梦<strong>乔伊·崔比安尼：</strong>噢，我也是。现在让我们做完这件事去睡觉吧。</p></blockquote><p>Dream **Monica Geller: **Okay! There&#39;s only one left, three letter word, not dog but…</p><blockquote><p>好的！只剩下一个三个字母的单词，不是狗而是…</p></blockquote><p>Dream **Joey Tribbiani: **Cat.</p><blockquote><p>梦<strong>乔伊·崔比安尼：</strong>猫。</p></blockquote><p>Dream **Monica Geller: **Yes! You are so smart! (Kisses him.) I love you.</p><blockquote><p>是的！你真聪明！（吻他）我爱你。</p></blockquote><p>Dream **Joey Tribbiani: **I love you too.</p><blockquote><p>我也爱你。</p></blockquote><p><em>(They hug.)</em></p><blockquote><p><em>（他们拥抱。）</em></p></blockquote><p>[Cut back to Joey in bed, he&#39;s smiling, enjoying the dream as he wakes up. Suddenly, he realized what he was dreaming about and bolts upright in bed.]</p><blockquote><p>[回到躺在床上的乔伊，他微笑着，享受着醒来时的梦境。突然，他意识到自己在做梦，并在床上直立起来。]</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Central Perk, everyone is there but Ross and Joey. Gunther hands them the bill, and Chandler gives some money to pay it.</em></p><blockquote><p>🎬 <em>中央公园，除了罗斯和乔伊，所有人都在。冈瑟把账单递给他们，钱德勒给了他们一些钱来支付。</em></p></blockquote>`,30),r(p,{src:`/audio/friends/S05/S05E16/014.mp3`}),c[50]||=i(),c[51]||=a(`strong`,null,`Rachel Green:`,-1),c[52]||=i(` (looking at the bill) Uhh, we still need a tip.`,-1),c[53]||=a(`blockquote`,null,[a(`p`,null,`（看着账单）嗯，我们还需要小费。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/015.mp3`}),c[54]||=i(),c[55]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[56]||=i(` All right. Hold on. (She starts digging in the chair.) I got it. Nickel! (Donates it.) How much more do we need?`,-1),c[57]||=a(`blockquote`,null,[a(`p`,null,`好的。等等（她开始在椅子上挖洞。）我明白了。镍！（捐赠）我们还需要多少？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/016.mp3`}),c[58]||=i(),c[59]||=a(`strong`,null,`Rachel Green:`,-1),c[60]||=i(` A couple of bucks.`,-1),c[61]||=a(`blockquote`,null,[a(`p`,null,`两块钱。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/017.mp3`}),c[62]||=i(),c[63]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[64]||=i(` Okay, dime! (Donates that.) You guys should probably keep talking; this could take a while. (Finds something else.) Oh no, wait! Look it! Whoa! (Looks at it.) Oh my God, this is a police badge!`,-1),c[65]||=a(`blockquote`,null,[a(`p`,null,`好的，一角硬币！（捐赠）你们应该继续说话；这可能需要一段时间。（找到别的东西）哦，不，等等！看！哇！（看着它）哦，天哪，这是警察徽章！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/018.mp3`}),c[66]||=i(),c[67]||=a(`strong`,null,`Monica Geller:`,-1),c[68]||=i(` Wow!`,-1),c[69]||=a(`blockquote`,null,[a(`p`,null,`哇！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/019.mp3`}),c[70]||=i(),c[71]||=a(`strong`,null,`Chandler Bing:`,-1),c[72]||=i(` Oh that's so cool! Why would a cop come in here though? They don't serve donuts. (No one laughs.) Y'know what actually, could you discover the badge again? I think I can come up with something better than that.`,-1),c[73]||=a(`blockquote`,null,[a(`p`,null,`哦，太酷了！为什么会有警察来这里？他们不供应甜甜圈。（没有人笑）你知道吗，你能再发现一次徽章吗？我想我能想出比这更好的办法。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/020.mp3`}),c[74]||=i(),c[75]||=a(`strong`,null,`Rachel Green:`,-1),c[76]||=i(` Phoebe, I bet somebody's missing that badge.`,-1),c[77]||=a(`blockquote`,null,[a(`p`,null,`菲比，我打赌有人丢了那个徽章。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/021.mp3`}),c[78]||=i(),c[79]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[80]||=i(` Yeah, I should probably take it back. Ooh, but you know what? While I'm at the police station, I could check their Ten Most Wanted lists because my friend Fritzy has been like number 11 forever, so this could be her year! (She crosses her fingers in hope.)`,-1),c[81]||=a(`blockquote`,null,[a(`p`,null,`是的，我应该把它拿回去。哦，但是你知道吗？当我在警察局的时候，我可以查看他们的十大通缉犯名单，因为我的朋友弗里茨永远都是11号人物，所以今年可能是她的一年！（她在希望中交叉手指。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/022.mp3`}),c[82]||=i(),c[83]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[84]||=i(` (entering) Hey, you guys!`,-1),c[85]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿，你们这些家伙！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/023.mp3`}),c[86]||=i(),c[87]||=a(`strong`,null,`Chandler Bing:`,-1),c[88]||=i(` Hey!`,-1),c[89]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/024.mp3`}),c[90]||=i(),c[91]||=a(`strong`,null,`Rachel Green:`,-1),c[92]||=i(` Hey Joey!`,-1),c[93]||=a(`blockquote`,null,[a(`p`,null,`嘿，乔伊！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/025.mp3`}),c[94]||=i(),c[95]||=a(`strong`,null,`Monica Geller:`,-1),c[96]||=i(` Hey.`,-1),c[97]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/026.mp3`}),c[98]||=i(),c[99]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[100]||=i(` (To Monica) Hey. That uh, that my sweatshirt?`,-1),c[101]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡）嘿。那件我的运动衫？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/027.mp3`}),c[102]||=i(),c[103]||=a(`strong`,null,`Monica Geller:`,-1),c[104]||=i(` Oh yes, it is. I'm sorry I borrowed it, I was cold. I hope its okay?`,-1),c[105]||=a(`blockquote`,null,[a(`p`,null,`哦，是的。对不起，我借了它，我很冷。我希望没事吧？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/028.mp3`}),c[106]||=i(),c[107]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[108]||=i(` Well uh, it's just that uh, y'know if-if you're gonna be wearing someone's sweatshirt shouldn't it be your boyfriends--and I’m not him.`,-1),c[109]||=a(`blockquote`,null,[a(`p`,null,`嗯，只是，嗯，你知道如果你要穿别人的运动衫，不应该是你的男朋友，而我不是他。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/029.mp3`}),c[110]||=i(),c[111]||=a(`strong`,null,`Monica Geller:`,-1),c[112]||=i(` I'm sorry, I'll give it back to you.`,-1),c[113]||=a(`blockquote`,null,[a(`p`,null,`对不起，我会还给你的。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/030.mp3`}),c[114]||=i(),c[115]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[116]||=i(` No-no! No! I mean it's gonna be all smelling like Monica!`,-1),c[117]||=a(`blockquote`,null,[a(`p`,null,`不，不！不我的意思是闻起来都像莫妮卡！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/031.mp3`}),c[118]||=i(),c[119]||=a(`strong`,null,`Monica Geller:`,-1),c[120]||=i(` Are you saying I smell bad?`,-1),c[121]||=a(`blockquote`,null,[a(`p`,null,`你是说我闻起来很难闻？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/032.mp3`}),c[122]||=i(),c[123]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[124]||=i(` No! No, you smell like a meadow. (Pause.) I'm sorry. (Runs to the bathroom.)`,-1),c[125]||=a(`blockquote`,null,[a(`p`,null,`不！不，你闻起来像草地。（停顿）对不起。（跑向浴室。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/033.mp3`}),c[126]||=i(),c[127]||=a(`strong`,null,`Monica Geller:`,-1),c[128]||=i(` What's with him?`,-1),c[129]||=a(`blockquote`,null,[a(`p`,null,`他怎么了？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/034.mp3`}),c[130]||=i(),c[131]||=a(`strong`,null,`Chandler Bing:`,-1),c[132]||=i(` Oh, y'know what? The last time Joey went to a meadow, his mother was shot by a hunter.`,-1),c[133]||=a(`blockquote`,null,[a(`p`,null,`哦，你知道吗？乔伊最后一次去草地时，他的母亲被猎人射杀了。`)],-1),c[134]||=a(`hr`,null,null,-1),c[135]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`A couch store, Ross is trying to decide on a new couch for his place. He has dragged Rachel along for the trip, and she's not too happy about it. Ross is sitting on it in different ways to see how it feels. He tries to just sit on it normally, and then he tries flopping on it. One thing about this couch, it's huge. It's like twice the size of a normal full size couch. Whoever designed this thing, needs help and fast.`)],-1),c[136]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`一家沙发店，罗斯正试着为自己的位置选择一张新沙发。他把瑞秋拖去旅行，她对此不太高兴。罗斯以不同的方式坐在沙发上，看看它的感觉如何。他试着正常地坐在上面，然后试着在上面摔倒。这张沙发的一个特点是，它很大。它的大小是它的两倍普通的全尺寸沙发。无论是谁设计了这个东西，都需要帮助和快速。`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/035.mp3`}),c[137]||=i(),c[138]||=a(`strong`,null,`Rachel Green:`,-1),c[139]||=i(` (disgusted at Ross's antics) Ugh!`,-1),c[140]||=a(`blockquote`,null,[a(`p`,null,`（厌恶罗斯的滑稽动作）啊！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/036.mp3`}),c[141]||=i(),c[142]||=a(`strong`,null,`Ross Geller:`,-1),c[143]||=i(` (To Rachel) Yeah, I still don't know. (To the salesman who is hovering nearby) I'm sorry I just wanna make sure that I bought the right couch. I need a couch that says, "Kids welcome here." But that also says, (In a sexy voice) "Come here to me!"`,-1),c[144]||=a(`blockquote`,null,[a(`p`,null,`（对瑞秋）是的，我还是不知道。（对徘徊在附近的推销员说）对不起，我只是想确定我买的沙发是对的。我需要一个沙发，上面写着“欢迎孩子们到这里来”，但上面也写着（用性感的声音）“到我这里来！”`)],-1),r(p,{src:`/audio/friends/S05/S05E16/037.mp3`}),c[145]||=i(),c[146]||=a(`strong`,null,`Rachel Green:`,-1),c[147]||=i(` What?! You say that to kids?!!`,-1),c[148]||=a(`blockquote`,null,[a(`p`,null,`什么？！你对孩子们这么说？！！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/038.mp3`}),c[149]||=i(),c[150]||=a(`strong`,null,`Ross Geller:`,-1),c[151]||=i(` No! No! No! The "Come here to me" is y'know for the ladies.`,-1),c[152]||=a(`blockquote`,null,[a(`p`,null,`不！不不“到我这里来”是你知道的女士的名字。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/039.mp3`}),c[153]||=i(),c[154]||=a(`strong`,null,`Rachel Green:`,-1),c[155]||=i(` Ross, honey, it's a nice couch. It's not a magic couch.`,-1),c[156]||=a(`blockquote`,null,[a(`p`,null,`罗斯，亲爱的，这沙发不错。这不是一个神奇的沙发。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/040.mp3`}),c[157]||=i(),c[158]||=a(`strong`,null,`The Salesman:`,-1),c[159]||=i(` You picked a great couch.`,-1),c[160]||=a(`blockquote`,null,[a(`p`,null,`你选了一张很棒的沙发。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/041.mp3`}),c[161]||=i(),c[162]||=a(`strong`,null,`Ross Geller:`,-1),c[163]||=i(` Yeah?`,-1),c[164]||=a(`blockquote`,null,[a(`p`,null,`是吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/042.mp3`}),c[165]||=i(),c[166]||=a(`strong`,null,`The Salesman:`,-1),c[167]||=i(` Yeah. Could you just sign right here please? (Hands him a clipboard.)`,-1),c[168]||=a(`blockquote`,null,[a(`p`,null,`是的。请你在这里签名好吗？（递给他一个剪贴板。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/043.mp3`}),c[169]||=i(),c[170]||=a(`strong`,null,`Ross Geller:`,-1),c[171]||=i(` Oh, sure. Whoa-whoa, what's this? The delivery charge is almost as much as the couch!`,-1),c[172]||=a(`blockquote`,null,[a(`p`,null,`哦，当然。哇，这是什么？送货费几乎和沙发一样多！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/044.mp3`}),c[173]||=i(),c[174]||=a(`strong`,null,`Rachel Green:`,-1),c[175]||=i(` Wait! No, that's ridiculous. Come on, he lives three blocks away!`,-1),c[176]||=a(`blockquote`,null,[a(`p`,null,`等等！不，那太荒谬了。拜托，他住三个街区远！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/045.mp3`}),c[177]||=i(),c[178]||=a(`strong`,null,`Ross Geller:`,-1),c[179]||=i(` Yeah, y'know what? I'll take it myself, thank you! (He signs the form and hands it back to the salesman.) All right Rach, let's go! (He picks up one end of the couch.)`,-1),c[180]||=a(`blockquote`,null,[a(`p`,null,`是的，你知道吗？我自己买，谢谢！（他在表格上签名，然后把它交还给推销员。）好了，瑞秋，我们走！（他拿起沙发的一端。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/046.mp3`}),c[181]||=i(),c[182]||=a(`strong`,null,`Rachel Green:`,-1),c[183]||=i(` Yeah! (She puts on her coat and turns around and sees Ross is expecting her to help.) (Laughing.) Are you kiddin'?`,-1),c[184]||=a(`blockquote`,null,[a(`p`,null,`是啊！（她穿上外套，转过身，看到罗斯在等她帮忙。）（笑）你在开玩笑吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/047.mp3`}),c[185]||=i(),c[186]||=a(`strong`,null,`Ross Geller:`,-1),c[187]||=i(` Oh, come on it's only three blocks! And-and, it's not very heavy, try it! Come on! Come on!`,-1),c[188]||=a(`blockquote`,null,[a(`p`,null,`噢，拜托，只有三个街区！而且，它不是很重，试试看！来吧来吧`)],-1),r(p,{src:`/audio/friends/S05/S05E16/048.mp3`}),c[189]||=i(),c[190]||=a(`strong`,null,`Rachel Green:`,-1),c[191]||=i(` (Disgustedly she goes and tries to pick up the couch. Much to her amazement, she is successful.) Oh. Oh! I can do it!`,-1),c[192]||=a(`blockquote`,null,[a(`p`,null,`（她厌恶地走过去，试图拿起沙发。令她惊讶的是，她成功了。）哦。哦我能做到！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/049.mp3`}),c[193]||=i(),c[194]||=a(`strong`,null,`Ross Geller:`,-1),c[195]||=i(` Yeah!`,-1),c[196]||=a(`blockquote`,null,[a(`p`,null,`是啊！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/050.mp3`}),c[197]||=i(),c[198]||=a(`strong`,null,`The Salesman:`,-1),c[199]||=i(` You two are really gonna enjoy that couch.`,-1),c[200]||=a(`blockquote`,null,[a(`p`,null,`你们两个一定会喜欢那个沙发的。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/051.mp3`}),c[201]||=i(),c[202]||=a(`strong`,null,`Ross Geller:`,-1),c[203]||=i(` Oh yeah, we're uh, yeah we're not together. (He starts backing out of the store.)`,-1),c[204]||=a(`blockquote`,null,[a(`p`,null,`哦，是的，我们呃，是的，我们不在一起。（他开始退出商店。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/052.mp3`}),c[205]||=i(),c[206]||=a(`strong`,null,`The Salesman:`,-1),c[207]||=i(` Ohh, okay. (Laughs.) Something didn't quite add up there. (Ross stops, walks back to talk to the salesman, and in the process pushes Rachel up against a wall.)`,-1),c[208]||=a(`blockquote`,null,[a(`p`,null,`哦，好的。（笑）那里有些事情不太对劲。（罗斯停了下来，走回去和销售员说话，在这个过程中，他把瑞秋推到了墙上。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/053.mp3`}),c[209]||=i(),c[210]||=a(`strong`,null,`Rachel Green:`,-1),c[211]||=i(` Ross!`,-1),c[212]||=a(`blockquote`,null,[a(`p`,null,`罗斯！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/054.mp3`}),c[213]||=i(),c[214]||=a(`strong`,null,`Ross Geller:`,-1),c[215]||=i(` What's that supposed to mean?`,-1),c[216]||=a(`blockquote`,null,[a(`p`,null,`那是什么意思？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/055.mp3`}),c[217]||=i(),c[218]||=a(`strong`,null,`Rachel Green:`,-1),c[219]||=i(` Ross!`,-1),c[220]||=a(`blockquote`,null,[a(`p`,null,`罗斯！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/056.mp3`}),c[221]||=i(),c[222]||=a(`strong`,null,`The Salesman:`,-1),c[223]||=i(` Well you, her, I mean, she's very…y'know. And you're like…y'know.`,-1),c[224]||=a(`blockquote`,null,[a(`p`,null,`嗯，你，她，我是说，她非常……你知道。你就像…你知道的。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/057.mp3`}),c[225]||=i(),c[226]||=a(`strong`,null,`Ross Geller:`,-1),c[227]||=i(` Not that it's any of your business, but we did go out.`,-1),c[228]||=a(`blockquote`,null,[a(`p`,null,`这不关你的事，但我们确实出去了。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/058.mp3`}),c[229]||=i(),c[230]||=a(`strong`,null,`The Salesman:`,-1),c[231]||=i(` Really? You two?`,-1),c[232]||=a(`blockquote`,null,[a(`p`,null,`真的吗？你们两个？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/059.mp3`}),c[233]||=i(),c[234]||=a(`strong`,null,`Ross Geller:`,-1),c[235]||=i(` Yeah! Rach?`,-1),c[236]||=a(`blockquote`,null,[a(`p`,null,`是啊！瑞秋？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/060.mp3`}),c[237]||=i(),c[238]||=a(`strong`,null,`Rachel Green:`,-1),c[239]||=i(` Come on, I don't really want to be doing this right now. I am carrying a very heavy couch.`,-1),c[240]||=a(`blockquote`,null,[a(`p`,null,`拜托，我现在真的不想这么做。我背着一张很重的沙发。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/061.mp3`}),c[241]||=i(),c[242]||=a(`strong`,null,`Ross Geller:`,-1),c[243]||=i(` Then tell him quickly.`,-1),c[244]||=a(`blockquote`,null,[a(`p`,null,`那快告诉他。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/062.mp3`}),c[245]||=i(),c[246]||=a(`strong`,null,`Rachel Green:`,-1),c[247]||=i(` (To Ross) Fine! (To the salesman) We went out.`,-1),c[248]||=a(`blockquote`,null,[a(`p`,null,`（对罗斯）很好！（对售货员）我们出去了。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/063.mp3`}),c[249]||=i(),c[250]||=a(`strong`,null,`Ross Geller:`,-1),c[251]||=i(` Not only did we go out, we did it 298 times!`,-1),c[252]||=a(`blockquote`,null,[a(`p`,null,`我们不仅出去了，还出去了298次！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/064.mp3`}),c[253]||=i(),c[254]||=a(`strong`,null,`Rachel Green:`,-1),c[255]||=i(` Ross!! Oh my--ugh!! You kept count?! You are such a loser!`,-1),c[256]||=a(`blockquote`,null,[a(`p`,null,`罗斯！！哦，天哪！！你数数了？！你真是个失败者！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/065.mp3`}),c[257]||=t(` <strong>Ross Geller:</strong> A loser you did it with (To the salesman) 298 times!<blockquote><p>一个失败者，你（对推销员）干了298次！</p></blockquote><p><em>(Rachel pushes on the couch and pushes Ross out the door.)</em></p><blockquote><p><em>（瑞秋推了推沙发，把罗斯推出门外。）</em></p></blockquote><hr><p>🎬 <em>Outside of Central Perk, Phoebe is exiting and sees a woman put out her cigarette on a tree.</em></p><blockquote><p>🎬 <em>在中央公园外，菲比正在离开，看到一名妇女在树上熄灭香烟。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S05/S05E16/066.mp3`}),c[258]||=i(),c[259]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[260]||=i(` Oh. Oh! Ma'am? Excuse me, ma'am?`,-1),c[261]||=a(`blockquote`,null,[a(`p`,null,`哦。哦太太？对不起，女士？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/067.mp3`}),c[262]||=i(),c[263]||=a(`strong`,null,`The Smoking Woman:`,-1),c[264]||=i(` Yes?`,-1),c[265]||=a(`blockquote`,null,[a(`p`,null,`是吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/068.mp3`}),c[266]||=i(),c[267]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[268]||=i(` You can't put your cigarette out on a tree!`,-1),c[269]||=a(`blockquote`,null,[a(`p`,null,`你不能把香烟熄灭在树上！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/069.mp3`}),c[270]||=i(),c[271]||=a(`strong`,null,`The Smoking Woman:`,-1),c[272]||=i(` Yeah I can, it worked real well.`,-1),c[273]||=a(`blockquote`,null,[a(`p`,null,`是的，我可以，它工作得很好。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/070.mp3`}),c[274]||=i(),c[275]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[276]||=i(` No but you shouldn't! Don't ever do that again.`,-1),c[277]||=a(`blockquote`,null,[a(`p`,null,`不，但你不应该！不要再那样做了。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/071.mp3`}),c[278]||=i(),c[279]||=a(`strong`,null,`The Smoking Woman:`,-1),c[280]||=i(` I won't! (Turns away) Until I have my next cigarette.`,-1),c[281]||=a(`blockquote`,null,[a(`p`,null,`我不会！（转身）直到我抽下一支烟。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/072.mp3`}),c[282]||=i(),c[283]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[284]||=i(` Hold it! (Grabs the badge) N.Y.P.D! Freeze punk!`,-1),c[285]||=a(`blockquote`,null,[a(`p`,null,`等等！（抓起警徽）纽约警察局！别动，朋克！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/073.mp3`}),c[286]||=i(),c[287]||=a(`strong`,null,`The Smoking Woman:`,-1),c[288]||=i(` What?!`,-1),c[289]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/074.mp3`}),c[290]||=i(),c[291]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[292]||=i(` Yeah that's right you are so busted. (To no one in particular.) Book 'em.`,-1),c[293]||=a(`blockquote`,null,[a(`p`,null,`是的，没错，你被抓到了。（没有特别对任何人）预订。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/075.mp3`}),c[294]||=i(),c[295]||=a(`strong`,null,`The Smoking Woman:`,-1),c[296]||=i(` Who are you talking too?`,-1),c[297]||=a(`blockquote`,null,[a(`p`,null,`你也在跟谁说话？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/076.mp3`}),c[298]||=i(),c[299]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[300]||=i(` Save it Red! Unless you wanna spend the night in the slammer, you apologize to the tree.`,-1),c[301]||=a(`blockquote`,null,[a(`p`,null,`保存它红色！除非你想在垃圾桶里过夜，否则你得向树道歉。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/077.mp3`}),c[302]||=i(),c[303]||=a(`strong`,null,`The Smoking Woman:`,-1),c[304]||=i(` I am not going to apologize to a tree!`,-1),c[305]||=a(`blockquote`,null,[a(`p`,null,`我不会向树道歉的！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/078.mp3`}),c[306]||=i(),c[307]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[308]||=i(` You apologize to the tree right now or I am calling for backup. (The woman calls her bluff.) (Screaming at no one in particular) Backup! Backup!!`,-1),c[309]||=a(`blockquote`,null,[a(`p`,null,`你现在就向圣诞树道歉，否则我会打电话要求支援。（那个女人叫她虚张声势。）（没有特别冲任何人尖叫）支援！备份`)],-1),r(p,{src:`/audio/friends/S05/S05E16/079.mp3`}),c[310]||=i(),c[311]||=a(`strong`,null,`The Smoking Woman:`,-1),c[312]||=i(` I-I'm sorry! Sorry.`,-1),c[313]||=a(`blockquote`,null,[a(`p`,null,`对不起！很抱歉`)],-1),r(p,{src:`/audio/friends/S05/S05E16/080.mp3`}),c[314]||=i(),c[315]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[316]||=i(` Okay, cancel backup! Cancel backup!`,-1),c[317]||=a(`blockquote`,null,[a(`p`,null,`好的，取消备份！取消备份！`)],-1),c[318]||=a(`hr`,null,null,-1),c[319]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Ross's building's lobby, he and Rachel are about to attempt to take the couch upstairs.`)],-1),c[320]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`罗斯所在大楼的大厅，他和瑞秋准备把沙发搬到楼上。`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/081.mp3`}),c[321]||=i(),c[322]||=a(`strong`,null,`Ross Geller:`,-1),c[323]||=i(` Okay. (Throws off the last cushion.)`,-1),c[324]||=a(`blockquote`,null,[a(`p`,null,`好的。（扔掉最后一个垫子。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/082.mp3`}),c[325]||=i(),c[326]||=a(`strong`,null,`Rachel Green:`,-1),c[327]||=i(` Ross, didn't you say that there was an elevator in here?`,-1),c[328]||=a(`blockquote`,null,[a(`p`,null,`罗斯，你不是说这里有电梯吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/083.mp3`}),c[329]||=i(),c[330]||=a(`strong`,null,`Ross Geller:`,-1),c[331]||=i(` Uhh, yes I did but there isn't. Okay, here we go.`,-1),c[332]||=a(`blockquote`,null,[a(`p`,null,`嗯，是的，我有，但没有。好了，开始吧。`)],-1),c[333]||=a(`p`,null,[a(`em`,null,`(They start the attempt. Ross is going backwards and reaches the first landing. This staircase has three steps then a landing, makes a 90-degree turn, and has more steps before another landing and another 90-degree turn.)`)],-1),c[334]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们开始尝试。罗斯向后走，到达第一个楼梯平台。这个楼梯有三个台阶，然后是一个楼梯平台，做90度转弯，在另一个楼梯平台和另一个90度转弯之前有更多的台阶。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/084.mp3`}),c[335]||=i(),c[336]||=a(`strong`,null,`Ross Geller:`,-1),c[337]||=i(` Okay, go left. Left! Left! (The bottom of the couch is hitting the railing.)`,-1),c[338]||=a(`blockquote`,null,[a(`p`,null,`好的，向左走。左边左边（沙发的底部碰到了栏杆。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/085.mp3`}),c[339]||=i(),c[340]||=a(`strong`,null,`Rachel Green:`,-1),c[341]||=i(` Okay, y'know what? There is no more left, left!`,-1),c[342]||=a(`blockquote`,null,[a(`p`,null,`好吧，你知道吗？再也没有剩下的了，剩下的！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/086.mp3`}),c[343]||=i(),c[344]||=a(`strong`,null,`Ross Geller:`,-1),c[345]||=i(` Oh okay, lift it straight up over your head! Straight up over your head! You can do it! You can do it! (She gets it lifted up and they make the first turn.) Okay. You got it?`,-1),c[346]||=a(`blockquote`,null,[a(`p`,null,`哦，好的，把它举过头顶！直过你的头！你能行！你能行！（她把车抬起来，他们第一个转弯。）好的。明白了吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/087.mp3`}),c[347]||=i(),c[348]||=a(`strong`,null,`Rachel Green:`,-1),c[349]||=i(` Yeah.`,-1),c[350]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/088.mp3`}),c[351]||=i(),c[352]||=a(`strong`,null,`Ross Geller:`,-1),c[353]||=i(` Good-good-good.`,-1),c[354]||=a(`blockquote`,null,[a(`p`,null,`很好。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/089.mp3`}),c[355]||=i(),c[356]||=a(`strong`,null,`Rachel Green:`,-1),c[357]||=i(` Oh-oh!`,-1),c[358]||=a(`blockquote`,null,[a(`p`,null,`噢！`)],-1),c[359]||=a(`p`,null,[a(`em`,null,`(She can't stay at the end as the couch rounds the turn so she shifts to the back corner of the couch and is at a 90-degree angle to it.)`)],-1),c[360]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（当沙发转弯时，她不能呆在末端，所以她会移到沙发的后角，并与沙发成90度角。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/090.mp3`}),c[361]||=i(),c[362]||=a(`strong`,null,`Ross Geller:`,-1),c[363]||=i(` Yeah, you got it right? You got it right? You got it?`,-1),c[364]||=a(`blockquote`,null,[a(`p`,null,`是的，你说得对吗？你说得对吗？明白了吗？`)],-1),c[365]||=a(`p`,null,[a(`em`,null,`(She don't got it as the couch slips out of their grips and falls over the bottom railing.)`)],-1),c[366]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（当沙发从他们手中滑出，从底部栏杆上摔下来时，她没有抓住。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/091.mp3`}),c[367]||=i(),c[368]||=a(`strong`,null,`Rachel Green:`,-1),c[369]||=i(` Any chance you think the couch looks good there?`,-1),c[370]||=a(`blockquote`,null,[a(`p`,null,`你觉得那里的沙发好看吗？`)],-1),c[371]||=a(`hr`,null,null,-1),c[372]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Chandler and Joey's, Phoebe is telling Chandler and Monica how she fought crime in her own way with the badge she found.`)],-1),c[373]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`钱德勒和乔伊家，菲比正在告诉钱德勒和莫妮卡她是如何用找到的徽章以自己的方式与犯罪作斗争的。`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/092.mp3`}),c[374]||=i(),c[375]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[376]||=i(` …so this guy was all (Mumbles.) And I'm all, Buffay, Homicide. (Flashes the badge.) It was just so cool!`,-1),c[377]||=a(`blockquote`,null,[a(`p`,null,`……所以这家伙（咕哝着）和我都是，布菲，凶杀。（闪烁着徽章）真是太酷了！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/093.mp3`}),c[378]||=i(),c[379]||=a(`strong`,null,`Monica Geller:`,-1),c[380]||=i(` (cooking something) Phoebe, you were supposed to take that back!`,-1),c[381]||=a(`blockquote`,null,[a(`p`,null,`（煮东西）菲比，你应该把它拿回去！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/094.mp3`}),c[382]||=i(),c[383]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[384]||=i(` I know but I'm having so much fun doing good deeds.`,-1),c[385]||=a(`blockquote`,null,[a(`p`,null,`我知道，但我做好事很开心。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/095.mp3`}),c[386]||=i(),c[387]||=a(`strong`,null,`Chandler Bing:`,-1),c[388]||=i(` Okay, but impersonating a police officer is a serious thing. You could get arrested.`,-1),c[389]||=a(`blockquote`,null,[a(`p`,null,`好吧，但冒充警察是件严肃的事。你可能会被捕。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/096.mp3`}),c[390]||=i(),c[391]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[392]||=i(` You could get arrested, right now! (Flashes the badge and they glare at her.) All right, yeah, I gotta take it back. I'm totally drunk with power. (She heads for the door just as Joey enters.)`,-1),c[393]||=a(`blockquote`,null,[a(`p`,null,`你可能会被逮捕，现在！（亮出警徽，他们瞪着她。）好吧，是的，我得把它拿回去。我完全被权力迷住了。（乔伊进来时，她朝门口走去。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/097.mp3`}),c[394]||=i(),c[395]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[396]||=i(` (To Joey) Hey.`,-1),c[397]||=a(`blockquote`,null,[a(`p`,null,`（对乔伊）嘿。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/098.mp3`}),c[398]||=i(),c[399]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[400]||=i(` (To Phoebe) Hey! (Sees that Monica's there.) Oh.`,-1),c[401]||=a(`blockquote`,null,[a(`p`,null,`（对菲比）嘿！（看到莫妮卡在那里）哦。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/099.mp3`}),c[402]||=i(),c[403]||=a(`strong`,null,`Chandler Bing:`,-1),c[404]||=i(` Hi, Joe.`,-1),c[405]||=a(`blockquote`,null,[a(`p`,null,`嗨，乔。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/100.mp3`}),c[406]||=i(),c[407]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[408]||=i(` Yeah, I didn’t know you guys were going to be here.`,-1),c[409]||=a(`blockquote`,null,[a(`p`,null,`是啊，我不知道你们会在这里。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/101.mp3`}),c[410]||=i(),c[411]||=a(`strong`,null,`Monica Geller:`,-1),c[412]||=i(` Hey Joey, sweetie, taste this. (Holds out a spoon for him.)`,-1),c[413]||=a(`blockquote`,null,[a(`p`,null,`嘿，乔伊，亲爱的，尝尝这个。（为他拿出一把勺子。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/102.mp3`}),c[414]||=i(),c[415]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[416]||=i(` (backing away) What?! Why?!`,-1),c[417]||=a(`blockquote`,null,[a(`p`,null,`（后退）什么？！为什么？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/103.mp3`}),c[418]||=i(),c[419]||=a(`strong`,null,`Monica Geller:`,-1),c[420]||=i(` What is going on with you?`,-1),c[421]||=a(`blockquote`,null,[a(`p`,null,`你怎么了？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/104.mp3`}),c[422]||=i(),c[423]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[424]||=i(` Nothing!`,-1),c[425]||=a(`blockquote`,null,[a(`p`,null,`没什么！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/105.mp3`}),c[426]||=i(),c[427]||=a(`strong`,null,`Chandler Bing:`,-1),c[428]||=i(` Oh, come on! You've been acting strange all day!`,-1),c[429]||=a(`blockquote`,null,[a(`p`,null,`哦，别这样！你一整天都表现得很奇怪！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/106.mp3`}),c[430]||=i(),c[431]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[432]||=i(` All right! There is something. I kinda had a dream, (pause) but I don't want to talk about it. (Starts for his room.)`,-1),c[433]||=a(`blockquote`,null,[a(`p`,null,`好吧！有些事。我有一个梦，（停顿）但我不想谈论它。（他动身去他的房间。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/107.mp3`}),c[434]||=i(),c[435]||=a(`strong`,null,`Chandler Bing:`,-1),c[436]||=i(` Whoa-whoa-whoa-whoa-whoa-what-what if Martin Luther King had said that? (Imitating what his famous speech would sound like.) I kinda have a dream! I don’t want to talk about it.`,-1),c[437]||=a(`blockquote`,null,[a(`p`,null,`哇，哇，哇，哇，如果马丁·路德·金那样说呢？（模仿他那著名的演讲）我有一个梦想！我不想谈论它。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/108.mp3`}),c[438]||=i(),c[439]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[440]||=i(` Well, it involved Monica.`,-1),c[441]||=a(`blockquote`,null,[a(`p`,null,`嗯，这涉及到莫妮卡。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/109.mp3`}),c[442]||=i(),c[443]||=a(`strong`,null,`Chandler Bing:`,-1),c[444]||=i(` You had a dream about a girl that I am seeing?! Oh, that is so cool! (To Monica) I can't tell you how many times I've dreamt about a girl that he was seeing. (Seeing Monica's stare.) (To Joey) Anyway we're talking about your dream. (To Monica) I love you. (To Joey) Your dream? (Leans in to listen closely.)`,-1),c[445]||=a(`blockquote`,null,[a(`p`,null,`你梦见了一个我正在约会的女孩？！哦，太酷了！（对莫妮卡）我不能告诉你有多少次我梦见了一个他正在约会的女孩。（看着莫妮卡的凝视）（对乔伊）不管怎样，我们在谈论你的梦想。（对莫妮卡）我爱你。（对乔伊）你的梦想？（倾身仔细听。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/110.mp3`}),c[446]||=i(),c[447]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[448]||=i(` Don't worry, there wasn't any sex in it or anything. I haven't dreamt about her like that since I found out about you two--ish.`,-1),c[449]||=a(`blockquote`,null,[a(`p`,null,`别担心，里面没有任何性的东西。自从我发现你们两个以后，我就再也没有这样梦见过她。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/111.mp3`}),c[450]||=i(),c[451]||=a(`strong`,null,`Monica Geller:`,-1),c[452]||=i(` What was the dream about?`,-1),c[453]||=a(`blockquote`,null,[a(`p`,null,`那个梦是关于什么的？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/112.mp3`}),c[454]||=i(),c[455]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[456]||=i(` Well, okay. You were my girlfriend and we were doing the crossword puzzle. Y'know like you guys were doing last night. So, that's it. I'm in love with Monica and I'll be moving out.`,-1),c[457]||=a(`blockquote`,null,[a(`p`,null,`好吧，好吧。你是我女朋友，我们在玩填字游戏。就像你们昨晚做的一样。就这样。我爱上了莫妮卡，我要搬出去了。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/113.mp3`}),c[458]||=i(),c[459]||=a(`strong`,null,`Monica Geller:`,-1),c[460]||=i(` Wait, Joey! Joey! That doesn’t mean that-that you're in love with me!`,-1),c[461]||=a(`blockquote`,null,[a(`p`,null,`等等，乔伊！乔伊！那并不意味着你爱上了我！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/114.mp3`}),c[462]||=i(),c[463]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[464]||=i(` It-it doesn’t?`,-1),c[465]||=a(`blockquote`,null,[a(`p`,null,`不是吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/115.mp3`}),c[466]||=i(),c[467]||=a(`strong`,null,`Monica Geller:`,-1),c[468]||=i(` No!`,-1),c[469]||=a(`blockquote`,null,[a(`p`,null,`不！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/116.mp3`}),c[470]||=i(),c[471]||=a(`strong`,null,`Chandler Bing:`,-1),c[472]||=i(` No, it can mean anything. Like uh, all of the sudden you're jealous because I've become the apartment stud.`,-1),c[473]||=a(`blockquote`,null,[a(`p`,null,`不，这可能意味着什么。就像，你突然嫉妒我，因为我成了公寓里的帅哥。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/117.mp3`}),c[474]||=i(),c[475]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[476]||=i(` That kinda sounds like your dream dude.`,-1),c[477]||=a(`blockquote`,null,[a(`p`,null,`听起来有点像你的梦中情人。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/118.mp3`}),c[478]||=i(),c[479]||=a(`strong`,null,`Monica Geller:`,-1),c[480]||=i(` Or, it could mean that-that you saw Chandler and me together and we y'know were being close and stuff and then you just want to have that with someone too.`,-1),c[481]||=a(`blockquote`,null,[a(`p`,null,`或者，这可能意味着你看到钱德勒和我在一起，我们很亲密，然后你也想和某人一起。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/119.mp3`}),c[482]||=i(),c[483]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[484]||=i(` In the dream I did enjoy the closeness.`,-1),c[485]||=a(`blockquote`,null,[a(`p`,null,`在梦中，我真的很享受这种亲密。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/120.mp3`}),c[486]||=i(),c[487]||=a(`strong`,null,`Monica Geller:`,-1),c[488]||=i(` Um-hmm.`,-1),c[489]||=a(`blockquote`,null,[a(`p`,null,`嗯。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/121.mp3`}),c[490]||=i(),c[491]||=a(`strong`,null,`Chandler Bing:`,-1),c[492]||=i(` Joey, look, are you attracted to Monica? Right here, right now, are you attracted to her?`,-1),c[493]||=a(`blockquote`,null,[a(`p`,null,`乔伊，你看，莫妮卡吸引你了吗？就在这里，现在，你被她吸引了吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/122.mp3`}),c[494]||=i(),c[495]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[496]||=i(` (looks at her) Not really.`,-1),c[497]||=a(`blockquote`,null,[a(`p`,null,`（看着她）不是真的。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/123.mp3`}),c[498]||=i(),c[499]||=a(`strong`,null,`Chandler Bing:`,-1),c[500]||=i(` Well there you have it!`,-1),c[501]||=a(`blockquote`,null,[a(`p`,null,`好了，给你！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/124.mp3`}),c[502]||=i(),c[503]||=a(`strong`,null,`Monica Geller:`,-1),c[504]||=i(` Well sure! I'm just wearing sweats! (Looking at Chandler and slowly realizing what his point is.) But that's good that you're not in love with me, because you just want a girlfriend!`,-1),c[505]||=a(`blockquote`,null,[a(`p`,null,`当然！我只是穿着汗衫！（看着钱德勒，慢慢意识到他的意思。）但你不爱我，这很好，因为你只是想要一个女朋友！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/125.mp3`}),c[506]||=i(),c[507]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[508]||=i(` No, I don't think it's just about just getting a girlfriend. Y'know? I mean, yeah, I can get a girlfriend! Yeah, we could sit in the chair and do crosswords, but y'know are we ever going to have y'know the closeness like-like you guys have?`,-1),c[509]||=a(`blockquote`,null,[a(`p`,null,`不，我不认为这只是为了找个女朋友。你知道吗？我是说，是的，我可以找个女朋友！是的，我们可以坐在椅子上玩纵横填字游戏，但你知道我们会像你们这样亲密吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/126.mp3`}),c[510]||=i(),c[511]||=a(`strong`,null,`Chandler Bing:`,-1),c[512]||=i(` Well y'know, Monica and I were friends before we started dating. So maybe-maybe that's it?`,-1),c[513]||=a(`blockquote`,null,[a(`p`,null,`你知道，莫妮卡和我在开始约会之前是朋友。也许就是这样？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/127.mp3`}),c[514]||=i(),c[515]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[516]||=i(` Friends first? That's interesting.`,-1),c[517]||=a(`blockquote`,null,[a(`p`,null,`朋友优先？那很有趣。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/128.mp3`}),c[518]||=i(),c[519]||=a(`strong`,null,`Monica Geller:`,-1),c[520]||=i(` You become friends after?`,-1),c[521]||=a(`blockquote`,null,[a(`p`,null,`之后你就成了朋友？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/129.mp3`}),c[522]||=i(),c[523]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[524]||=i(` No, never done that either.`,-1),c[525]||=a(`blockquote`,null,[a(`p`,null,`没有，也从来没有这样做过。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/130.mp3`}),c[526]||=i(),c[527]||=a(`strong`,null,`Rachel Green:`,-1),c[528]||=i(` (entering) Hey, umm, do you guys have that tape measure?`,-1),c[529]||=a(`blockquote`,null,[a(`p`,null,`嘿，嗯，你们有那个卷尺吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/131.mp3`}),c[530]||=i(),c[531]||=a(`strong`,null,`Chandler Bing:`,-1),c[532]||=i(` Oh yeah, it's actually in my bedroom.`,-1),c[533]||=a(`blockquote`,null,[a(`p`,null,`哦，是的，它实际上在我的卧室里。`)],-1),c[534]||=a(`p`,null,[a(`em`,null,`(Monica and Chandler both remember a special moment between them.)`)],-1),c[535]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（莫妮卡和钱德勒都记得他们之间的一个特殊时刻。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/132.mp3`}),c[536]||=i(),c[537]||=a(`strong`,null,`Monica Geller:`,-1),c[538]||=i(` (laughing) That's right.`,-1),c[539]||=a(`blockquote`,null,[a(`p`,null,`（笑）没错。`)],-1),c[540]||=a(`p`,null,[a(`em`,null,`(They realize the implication of their behavior, stop instantly and head for his bedroom. In the meanwhile, Joey is starring at Rachel in a seductive way.)`)],-1),c[541]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们意识到自己行为的含意，立即停下脚步，走向他的卧室。与此同时，乔伊正在以一种诱人的方式主演瑞秋。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/133.mp3`}),c[542]||=i(),c[543]||=a(`strong`,null,`Rachel Green:`,-1),c[544]||=i(` (noticing him) What's up Joey?`,-1),c[545]||=a(`blockquote`,null,[a(`p`,null,`（注意到他）乔伊怎么了？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/134.mp3`}),c[546]||=t(` <strong>Joey Tribbiani:</strong> (in a sexy voice) How you doin&#39;?<blockquote><p>（用性感的声音）你好吗？</p></blockquote><p><em>(Rachel is stunned.)</em></p><blockquote><p><em>（瑞秋愣住了。）</em></p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Outside Central Perk, Phoebe is walking up and notices a car that is parked half on the curb and right in front of the door, making it difficult for people to enter Central Perk.</em></p><blockquote><p>🎬 <em>在中央公园外，菲比走上前，注意到一辆车半停在路边，就停在门前，让人们很难进入中央公园。</em></p></blockquote>`,11),r(p,{src:`/audio/friends/S05/S05E16/135.mp3`}),c[547]||=i(),c[548]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[549]||=i(` Excuse me, is this your car?`,-1),c[550]||=a(`blockquote`,null,[a(`p`,null,`对不起，这是你的车吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/136.mp3`}),c[551]||=i(),c[552]||=a(`strong`,null,`Guy:`,-1),c[553]||=i(` Yeah.`,-1),c[554]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/137.mp3`}),c[555]||=i(),c[556]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[557]||=i(` Well I don't think it's very nice of you to park here, y'know you're blocking the entrance.`,-1),c[558]||=a(`blockquote`,null,[a(`p`,null,`我觉得你把车停在这里不太好，你知道你挡住了入口。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/138.mp3`}),c[559]||=i(),c[560]||=a(`strong`,null,`Guy:`,-1),c[561]||=i(` Don't worry about it. It's not a problem.`,-1),c[562]||=a(`blockquote`,null,[a(`p`,null,`别担心。这不是问题。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/139.mp3`}),c[563]||=i(),c[564]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[565]||=i(` Well, it's a problem for me, which means it's a problem for you 'cause I'm a cop. (Shows the badge.)`,-1),c[566]||=a(`blockquote`,null,[a(`p`,null,`嗯，这对我来说是个问题，也就是说，这对你来说是个问题，因为我是警察。（显示徽章。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/140.mp3`}),c[567]||=i(),c[568]||=a(`strong`,null,`Guy:`,-1),c[569]||=i(` (he reaches into the car and slams his siren on the roof.) So am I!`,-1),c[570]||=a(`blockquote`,null,[a(`p`,null,`（他把手伸进车里，把警笛重重地敲在车顶上。）我也是！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/141.mp3`}),c[571]||=i(),c[572]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[573]||=i(` Ohh, no. (Pause) Oh okay, so you're a cop which means you can park anywhere, 'cause I know that 'cause I'm a cop too. So, all right, keep up the good work. 10-4. (Tries to leave.)`,-1),c[574]||=a(`blockquote`,null,[a(`p`,null,`哦，不。（停顿）哦，好吧，你是警察，这意味着你可以在任何地方停车，因为我知道，因为我也是警察。所以，好吧，继续努力。10-4. （试图离开。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/142.mp3`}),c[575]||=i(),c[576]||=a(`strong`,null,`Cop:`,-1),c[577]||=i(` (stopping her) Hey, wait a second! So wait, what precinct are you with?`,-1),c[578]||=a(`blockquote`,null,[a(`p`,null,`（拦住她）嘿，等一下！等等，你在哪个警署？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/143.mp3`}),c[579]||=i(),c[580]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[581]||=i(` I-I'm with the umm, the 57th.`,-1),c[582]||=a(`blockquote`,null,[a(`p`,null,`我，我是57号。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/144.mp3`}),c[583]||=i(),c[584]||=a(`strong`,null,`Cop:`,-1),c[585]||=i(` Oh, I know a guy in homicide up there.`,-1),c[586]||=a(`blockquote`,null,[a(`p`,null,`哦，我认识一个杀人案的家伙。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/145.mp3`}),c[587]||=i(),c[588]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[589]||=i(` I'm in vice. Yeah, in fact I'm undercover right now. I'm a whore.`,-1),c[590]||=a(`blockquote`,null,[a(`p`,null,`我在卖淫。是的，事实上我现在是卧底。我是个妓女。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/146.mp3`}),c[591]||=i(),c[592]||=a(`strong`,null,`Cop:`,-1),c[593]||=i(` Who-who else is in vice up there?`,-1),c[594]||=a(`blockquote`,null,[a(`p`,null,`上面还有谁在卖淫？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/147.mp3`}),c[595]||=i(),c[596]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[597]||=i(` Umm, do you know, umm Sipowicz?`,-1),c[598]||=a(`blockquote`,null,[a(`p`,null,`嗯，你知道吗，嗯，西波维茨？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/148.mp3`}),c[599]||=i(),c[600]||=a(`strong`,null,`Cop:`,-1),c[601]||=i(` Sipowicz? No, I don't think so.`,-1),c[602]||=a(`blockquote`,null,[a(`p`,null,`西波维茨？不，我不这么认为。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/149.mp3`}),c[603]||=i(),c[604]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[605]||=i(` Yeah, big guy, kinda bald.`,-1),c[606]||=a(`blockquote`,null,[a(`p`,null,`是啊，大个子，有点秃顶。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/150.mp3`}),c[607]||=i(),c[608]||=a(`strong`,null,`Cop:`,-1),c[609]||=i(` No, I don't know him.`,-1),c[610]||=a(`blockquote`,null,[a(`p`,null,`不，我不认识他。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/151.mp3`}),c[611]||=i(),c[612]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[613]||=i(` (starts to walk away, but stops) Don’t try to call him or anything, 'cause he's not there, he's out. His umm, his partner just died.`,-1),c[614]||=a(`blockquote`,null,[a(`p`,null,`（开始走开，但停了下来）不要打电话给他或其他什么，因为他不在那里，他出去了。他的搭档刚刚去世。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/152.mp3`}),c[615]||=i(),c[616]||=a(`strong`,null,`Cop:`,-1),c[617]||=i(` Wow umm, tell Sipowicz I'm real sorry for his loss.`,-1),c[618]||=a(`blockquote`,null,[a(`p`,null,`哇，嗯，告诉西波维茨我真的为他的损失感到抱歉。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/153.mp3`}),c[619]||=i(),c[620]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[621]||=i(` I-I sure will, take care. (Starts walking off.)`,-1),c[622]||=a(`blockquote`,null,[a(`p`,null,`我当然会的，保重。（开始走开。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/154.mp3`}),c[623]||=i(),c[624]||=a(`strong`,null,`Cop:`,-1),c[625]||=i(` (following her) Hey by the way, I'm sure Sipowicz is gonna be all right. I heard that kid from Silver Spoons is really good. (Phoebe's stunned) And where did you find my badge?`,-1),c[626]||=a(`blockquote`,null,[a(`p`,null,`（跟着她）嘿，顺便说一句，我肯定西波维茨会没事的。我听说银汤匙的那个孩子真的很棒。（菲比惊呆了）你在哪里找到我的徽章？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/155.mp3`}),c[627]||=i(),c[628]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[629]||=i(` Oh. (She starts laughing. Then she throws the badge at him and runs away.)`,-1),c[630]||=a(`blockquote`,null,[a(`p`,null,`哦。（她笑了起来，然后把徽章扔向他，然后跑开了。）`)],-1),c[631]||=a(`hr`,null,null,-1),c[632]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, Joey is entering. Rachel is there getting some tools to help Ross out.`)],-1),c[633]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，乔伊进来了。瑞秋正在那里拿一些工具来帮助罗斯。`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/156.mp3`}),c[634]||=i(),c[635]||=a(`strong`,null,`Rachel Green:`,-1),c[636]||=i(` Hey! Joey, would you mind giving me and Ross a hand moving his couch?`,-1),c[637]||=a(`blockquote`,null,[a(`p`,null,`嘿！乔伊，你介意帮我和罗斯搬一下他的沙发吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/157.mp3`}),c[638]||=i(),c[639]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[640]||=i(` Oh, I'd love too, but I got acting class. But y'know what? I guess I can blow that off, (In a sexy voice) for you.`,-1),c[641]||=a(`blockquote`,null,[a(`p`,null,`哦，我也很想，但我上了表演课。但是你知道吗？我想我可以（用性感的声音）为你吹掉它。`)],-1),c[642]||=a(`p`,null,[a(`em`,null,`(He starts staring at her longingly.)`)],-1),c[643]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他开始渴望地盯着她。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/158.mp3`}),c[644]||=i(),c[645]||=a(`strong`,null,`Rachel Green:`,-1),c[646]||=i(` Thanks!`,-1),c[647]||=a(`blockquote`,null,[a(`p`,null,`谢谢！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/159.mp3`}),c[648]||=i(),c[649]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[650]||=i(` Uh, hey, Rach let me ask you something. Uh, I was just over there talking to Monica and Chandler, boy they are really tight.`,-1),c[651]||=a(`blockquote`,null,[a(`p`,null,`呃，嘿，瑞秋，让我问你一件事。我刚才在那边和Monica和Chandler聊天他们真的很亲密。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/160.mp3`}),c[652]||=i(),c[653]||=a(`strong`,null,`Rachel Green:`,-1),c[654]||=i(` I know.`,-1),c[655]||=a(`blockquote`,null,[a(`p`,null,`我知道。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/161.mp3`}),c[656]||=i(),c[657]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[658]||=i(` Yeah that's not such a bad situation they got going over there. I'm thinking of getting me one of those.`,-1),c[659]||=a(`blockquote`,null,[a(`p`,null,`是的，他们在那边的情况还不错。我想给我买一个。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/162.mp3`}),c[660]||=i(),c[661]||=a(`strong`,null,`Rachel Green:`,-1),c[662]||=i(` What's up Joe?`,-1),c[663]||=a(`blockquote`,null,[a(`p`,null,`乔，怎么了？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/163.mp3`}),c[664]||=i(),c[665]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[666]||=i(` Well, the reason I think Monica and Chandler are so great…`,-1),c[667]||=a(`blockquote`,null,[a(`p`,null,`嗯，我觉得莫妮卡和钱德勒很棒的原因…`)],-1),r(p,{src:`/audio/friends/S05/S05E16/164.mp3`}),c[668]||=i(),c[669]||=a(`strong`,null,`Rachel Green:`,-1),c[670]||=i(` Yeah?`,-1),c[671]||=a(`blockquote`,null,[a(`p`,null,`是吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/165.mp3`}),c[672]||=i(),c[673]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[674]||=i(` …is because they were friends first. Y'know? So I asked myself, "Who are my friends?" You and Phoebe, and I saw you first. So…`,-1),c[675]||=a(`blockquote`,null,[a(`p`,null,`……因为他们先是朋友。你知道吗？所以我问自己，“谁是我的朋友？”你和菲比，我第一次见到你。所以…`)],-1),r(p,{src:`/audio/friends/S05/S05E16/166.mp3`}),c[676]||=i(),c[677]||=a(`strong`,null,`Rachel Green:`,-1),c[678]||=i(` (laughing) What are you saying?`,-1),c[679]||=a(`blockquote`,null,[a(`p`,null,`（笑）你在说什么？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/167.mp3`}),c[680]||=i(),c[681]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[682]||=i(` I'm saying maybe you and I crank it up a notch.`,-1),c[683]||=a(`blockquote`,null,[a(`p`,null,`我是说也许你和我会把它提高一个档次。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/168.mp3`}),c[684]||=i(),c[685]||=a(`strong`,null,`Rachel Green:`,-1),c[686]||=i(` Y'know honey, umm, as uh, as flattered as I am that uh, you saw me first, uhh, I just, I-I don't think we should be cranking anything up.`,-1),c[687]||=a(`blockquote`,null,[a(`p`,null,`亲爱的，你知道吗，呃，我很荣幸你第一次看到我，呃，我只是，我觉得我们不应该做任何事情。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/169.mp3`}),c[688]||=i(),c[689]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[690]||=i(` I'll treat you real nice. (Pulls out a chair for her.)`,-1),c[691]||=a(`blockquote`,null,[a(`p`,null,`我会好好待你的。（为她拿出一把椅子。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/170.mp3`}),c[692]||=i(),c[693]||=a(`strong`,null,`Rachel Green:`,-1),c[694]||=i(` (laughs and pushes the chair back in) Yeah, well, y'know umm… No honey, listen I think it's a great idea to become friends with someone before you date them, but I think the way you do it is y'know you meet someone, become their friend, build a foundation, then you ask them out on a date. Don't hit on your existing friends!`,-1),c[695]||=a(`blockquote`,null,[a(`p`,null,`（笑着把椅子推回去）是的，嗯，你知道，亲爱的，听着，我认为在约会之前和别人交朋友是个好主意，但是我认为你这样做是因为你认识了某人，成为他们的朋友，建立了一个基金会，然后你邀请他们出去约会。不要攻击你现有的朋友！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/171.mp3`}),c[696]||=i(),c[697]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[698]||=i(` Won't-won't that take longer?`,-1),c[699]||=a(`blockquote`,null,[a(`p`,null,`会不会花更长的时间？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/172.mp3`}),c[700]||=i(),c[701]||=a(`strong`,null,`Rachel Green:`,-1),c[702]||=i(` Yeah. Yeah. Oh, but once you find it, ohh it's so worth the wait.`,-1),c[703]||=a(`blockquote`,null,[a(`p`,null,`是的。是 啊哦，但是一旦你找到它，哦，它是如此值得等待。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/173.mp3`}),c[704]||=i(),c[705]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[706]||=i(` Yeah. I understand. I understand. (Pause) Man, I wish I saw Phoebe first!`,-1),c[707]||=a(`blockquote`,null,[a(`p`,null,`是的。我理解。我理解。（停顿）伙计，我真希望我先见到菲比！`)],-1),c[708]||=a(`hr`,null,null,-1),c[709]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The lobby of Ross's building, he's sitting on the couch at the bottom of the stairs, and he's practicing enticing women to join him on the couch.`)],-1),c[710]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`罗斯大楼的大厅，他坐在楼梯底部的沙发上，他正在练习吸引女人加入他的沙发。`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/174.mp3`}),c[711]||=i(),c[712]||=a(`strong`,null,`Ross Geller:`,-1),c[713]||=i(` Come here to me. No-no, you come here to me.`,-1),c[714]||=a(`blockquote`,null,[a(`p`,null,`到我这儿来。不，不，你到我这里来。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/175.mp3`}),c[715]||=i(),c[716]||=a(`strong`,null,`Rachel Green:`,-1),c[717]||=i(` (entering) Hey Ross! I brought reinforcements.`,-1),c[718]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿，罗斯！我带来了增援部队。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/176.mp3`}),c[719]||=i(),c[720]||=a(`strong`,null,`Ross Geller:`,-1),c[721]||=i(` Oh great! What, you brought Joey?`,-1),c[722]||=a(`blockquote`,null,[a(`p`,null,`哦，太好了！什么，你把乔伊带来了？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/177.mp3`}),c[723]||=i(),c[724]||=a(`strong`,null,`Rachel Green:`,-1),c[725]||=i(` Well, I brought the next best thing.`,-1),c[726]||=a(`blockquote`,null,[a(`p`,null,`嗯，我带来了次好的东西。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/178.mp3`}),c[727]||=i(),c[728]||=a(`strong`,null,`Chandler Bing:`,-1),c[729]||=i(` (entering) Hey!`,-1),c[730]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/179.mp3`}),c[731]||=i(),c[732]||=a(`strong`,null,`Ross Geller:`,-1),c[733]||=i(` Chandler?! You brought Chandler?! The next best thing would be Monica!`,-1),c[734]||=a(`blockquote`,null,[a(`p`,null,`钱德勒？！你把钱德勒带来了？！下一个最好的就是莫妮卡！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/180.mp3`}),c[735]||=i(),c[736]||=a(`strong`,null,`Chandler Bing:`,-1),c[737]||=i(` Y'know, I would be offended, but Monica is freakishly strong, so…`,-1),c[738]||=a(`blockquote`,null,[a(`p`,null,`你知道，我会生气的，但莫妮卡异常强壮，所以…`)],-1),r(p,{src:`/audio/friends/S05/S05E16/181.mp3`}),c[739]||=i(),c[740]||=a(`strong`,null,`Ross Geller:`,-1),c[741]||=i(` Look, I-I drew a sketch about how we're gonna do it. (Showing them) Okay Rach, (points to the sketch) that's you. That's the couch. (Points again.)`,-1),c[742]||=a(`blockquote`,null,[a(`p`,null,`听着，我画了一张我们要怎么做的草图。（给他们看）好的，瑞秋，（指着草图）就是你。那是沙发。（我再说一遍。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/182.mp3`}),c[743]||=i(),c[744]||=a(`strong`,null,`Rachel Green:`,-1),c[745]||=i(` Whoa-oh, what's-what's that? (Points.)`,-1),c[746]||=a(`blockquote`,null,[a(`p`,null,`哇哦，那是什么？（点数）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/183.mp3`}),c[747]||=i(),c[748]||=a(`strong`,null,`Ross Geller:`,-1),c[749]||=i(` Oh, that's me.`,-1),c[750]||=a(`blockquote`,null,[a(`p`,null,`哦，是我。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/184.mp3`}),c[751]||=i(),c[752]||=a(`strong`,null,`Rachel Green:`,-1),c[753]||=i(` Wow! You certainly think a lot of yourself.`,-1),c[754]||=a(`blockquote`,null,[a(`p`,null,`哇！你肯定很看重自己。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/185.mp3`}),c[755]||=i(),c[756]||=a(`strong`,null,`Ross Geller:`,-1),c[757]||=i(` No! That's-that's my arm!`,-1),c[758]||=a(`blockquote`,null,[a(`p`,null,`不！那是我的手臂！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/186.mp3`}),c[759]||=i(),c[760]||=a(`strong`,null,`Chandler Bing:`,-1),c[761]||=i(` (looking at the sketch) Oh, I see. I thought you just really, really liked your new couch.`,-1),c[762]||=a(`blockquote`,null,[a(`p`,null,`（看着草图）哦，我明白了。我以为你真的很喜欢你的新沙发。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/187.mp3`}),c[763]||=i(),c[764]||=a(`strong`,null,`Ross Geller:`,-1),c[765]||=i(` Y'know what? Just-just follow my lead.`,-1),c[766]||=a(`blockquote`,null,[a(`p`,null,`你知道吗？跟着我走。`)],-1),c[767]||=a(`p`,null,[a(`em`,null,`(Chandler and Ross head for opposite ends of the couch.)`)],-1),c[768]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（钱德勒和罗斯走向沙发的另一端。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/188.mp3`}),c[769]||=i(),c[770]||=a(`strong`,null,`Rachel Green:`,-1),c[771]||=i(` Okay!`,-1),c[772]||=a(`blockquote`,null,[a(`p`,null,`好的！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/189.mp3`}),c[773]||=i(),c[774]||=a(`strong`,null,`Chandler Bing:`,-1),c[775]||=i(` Okay.`,-1),c[776]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/190.mp3`}),c[777]||=i(),c[778]||=a(`strong`,null,`Ross Geller:`,-1),c[779]||=i(` Come on, Chandler.`,-1),c[780]||=a(`blockquote`,null,[a(`p`,null,`来吧，钱德勒。`)],-1),c[781]||=a(`p`,null,[a(`em`,null,`(They pick up the couch and after throwing off the last pillow; Rachel helps out on Chandler's end.)`)],-1),c[782]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们拿起沙发，扔掉最后一个枕头；瑞秋在钱德勒那边帮忙。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/191.mp3`}),c[783]||=i(),c[784]||=a(`strong`,null,`Ross Geller:`,-1),c[785]||=i(` All right. (They start up the stairs. Ross is first.) Okay, here we go!`,-1),c[786]||=a(`blockquote`,null,[a(`p`,null,`好的。（他们上楼了，罗斯是第一个）好了，我们开始吧！`)],-1),c[787]||=a(`p`,null,[a(`em`,null,`(Chandler has moved forward and is now underneath the couch as it heads up the first set of stairs.)`)],-1),c[788]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（钱德勒向前移动，现在躺在沙发下面，沙发正朝第一组楼梯走去。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/192.mp3`}),c[789]||=i(),c[790]||=a(`strong`,null,`Ross Geller:`,-1),c[791]||=i(` All right, ready?`,-1),c[792]||=a(`blockquote`,null,[a(`p`,null,`好了，准备好了吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/193.mp3`}),c[793]||=i(),c[794]||=a(`strong`,null,`Chandler Bing:`,-1),c[795]||=i(` Yeah.`,-1),c[796]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/194.mp3`}),c[797]||=i(),c[798]||=a(`strong`,null,`Ross Geller:`,-1),c[799]||=i(` Turn.`,-1),c[800]||=a(`blockquote`,null,[a(`p`,null,`转身。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/195.mp3`}),c[801]||=i(),c[802]||=a(`strong`,null,`Chandler Bing:`,-1),c[803]||=i(` (straining) Okay.`,-1),c[804]||=a(`blockquote`,null,[a(`p`,null,`（紧张地）好的。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/196.mp3`}),c[805]||=i(),c[806]||=a(`strong`,null,`Ross Geller:`,-1),c[807]||=i(` Turn! Turn!`,-1),c[808]||=a(`blockquote`,null,[a(`p`,null,`转身！转动`)],-1),c[809]||=a(`p`,null,[a(`em`,null,`(As they turn the couch, Chandler gets sandwiched between the railing and the couch.)`)],-1),c[810]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（当他们转动沙发时，钱德勒被夹在栏杆和沙发之间。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/197.mp3`}),c[811]||=i(),c[812]||=a(`strong`,null,`Chandler Bing:`,-1),c[813]||=i(` Okay, I don't think we can turn anymore!`,-1),c[814]||=a(`blockquote`,null,[a(`p`,null,`好吧，我想我们再也转不过去了！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/198.mp3`}),c[815]||=i(),c[816]||=a(`strong`,null,`Rachel Green:`,-1),c[817]||=i(` Ross, I don't, I just don't think it's going to fit.`,-1),c[818]||=a(`blockquote`,null,[a(`p`,null,`罗斯，我不，我只是觉得它不合适。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/199.mp3`}),c[819]||=i(),c[820]||=a(`strong`,null,`Ross Geller:`,-1),c[821]||=i(` Oh yeah it will! Come on, up! Up-up-up! Up! Yes! Here we go! Pivot! (They start up the stairs again. Chandler is between the couch and the wall now.) Pivot! Piv-ot! Piv-et!! Piv-ett!!! Piv-et!`,-1),c[822]||=a(`blockquote`,null,[a(`p`,null,`哦，是的，会的！快点，起来！起来！向上的对我们走！支点（他们又上楼了。钱德勒现在在沙发和墙壁之间。）转动！皮奥特！Piv et！！皮维特！！！皮维特！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/200.mp3`}),c[823]||=i(),c[824]||=a(`strong`,null,`Chandler Bing:`,-1),c[825]||=i(` Shut up! Shut up! Shut up!!`,-1),c[826]||=a(`blockquote`,null,[a(`p`,null,`闭嘴！闭嘴！闭嘴！！`)],-1),c[827]||=a(`p`,null,[a(`em`,null,`(They set the couch down.)`)],-1),c[828]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们把沙发放下。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/201.mp3`}),c[829]||=i(),c[830]||=a(`strong`,null,`Ross Geller:`,-1),c[831]||=i(` Okay, I don't think it's going to pivot anymore.`,-1),c[832]||=a(`blockquote`,null,[a(`p`,null,`好吧，我想它不会再转动了。`)],-1),c[833]||=a(`p`,null,`Chandler and **Rachel Green: **You think?!`,-1),c[834]||=a(`blockquote`,null,[a(`p`,null,[i(`钱德勒和`),a(`strong`,null,`瑞秋·格林：`),i(`你觉得呢？！`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/202.mp3`}),c[835]||=i(),c[836]||=a(`strong`,null,`Ross Geller:`,-1),c[837]||=i(` All right, let's uh, let's bring it back down and-and try again.`,-1),c[838]||=a(`blockquote`,null,[a(`p`,null,`好吧，我们把它拿下来再试一次。`)],-1),c[839]||=a(`p`,null,[a(`em`,null,`(As they start back down the couch drops a little bit and gets jammed. They try to free it to no avail.)`)],-1),c[840]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（当他们回到沙发上时，沙发掉了一点，卡住了。他们试图把它放出来，但没有用。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/203.mp3`}),c[841]||=i(),c[842]||=a(`strong`,null,`Chandler Bing:`,-1),c[843]||=i(` Okay, yeah, I think it's really stuck now.`,-1),c[844]||=a(`blockquote`,null,[a(`p`,null,`好吧，是的，我想它现在真的卡住了。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/204.mp3`}),c[845]||=i(),c[846]||=a(`strong`,null,`Ross Geller:`,-1),c[847]||=i(` I can't believe that didn't work!`,-1),c[848]||=a(`blockquote`,null,[a(`p`,null,`我真不敢相信那没用！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/205.mp3`}),c[849]||=i(),c[850]||=a(`strong`,null,`Rachel Green:`,-1),c[851]||=i(` I know, me neither! I mean, you had a sketch!`,-1),c[852]||=a(`blockquote`,null,[a(`p`,null,`我知道，我也是！我是说，你有一张素描！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/206.mp3`}),c[853]||=i(),c[854]||=a(`strong`,null,`Chandler Bing:`,-1),c[855]||=i(` Oh, y'know, what did you mean when you said pivot?`,-1),c[856]||=a(`blockquote`,null,[a(`p`,null,`哦，你知道，你说支点是什么意思？`)],-1),c[857]||=a(`hr`,null,null,-1),c[858]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Chandler and Joey's, Joey is returning and finds Chandler, Monica, and Rachel are there.`)],-1),c[859]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`钱德勒和乔伊家，乔伊回来发现钱德勒、莫妮卡和瑞秋在那里。`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/207.mp3`}),c[860]||=i(),c[861]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[862]||=i(` (entering) Hey!`,-1),c[863]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/208.mp3`}),c[864]||=i(),c[865]||=a(`strong`,null,`Rachel Green:`,-1),c[866]||=i(` Hey! How's it going? Did you make any new friends?`,-1),c[867]||=a(`blockquote`,null,[a(`p`,null,`嘿！怎么样？你交新朋友了吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/209.mp3`}),c[868]||=i(),c[869]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[870]||=i(` Yeah, yeah, I met this woman. (Starts for his room.)`,-1),c[871]||=a(`blockquote`,null,[a(`p`,null,`是的，是的，我见过这个女人。（他动身去他的房间。）`)],-1),r(p,{src:`/audio/friends/S05/S05E16/210.mp3`}),c[872]||=i(),c[873]||=a(`strong`,null,`Chandler Bing:`,-1),c[874]||=i(` (stopping him) Hey, whoa-whoa! What's she like?`,-1),c[875]||=a(`blockquote`,null,[a(`p`,null,`（阻止他）嘿，哇哇！她长什么样？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/211.mp3`}),c[876]||=i(),c[877]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[878]||=i(` Uhh, well, she's…really good in bed.`,-1),c[879]||=a(`blockquote`,null,[a(`p`,null,`嗯，她…床上功夫真的很好。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/212.mp3`}),c[880]||=i(),c[881]||=a(`strong`,null,`Monica Geller:`,-1),c[882]||=i(` Joey, I thought you were gonna try to be friends first!`,-1),c[883]||=a(`blockquote`,null,[a(`p`,null,`乔伊，我还以为你会先做朋友呢！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/213.mp3`}),c[884]||=i(),c[885]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[886]||=i(` (To Rachel) Well look, hey, it's all your fault!`,-1),c[887]||=a(`blockquote`,null,[a(`p`,null,`（对瑞秋）听着，嘿，都是你的错！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/214.mp3`}),c[888]||=i(),c[889]||=a(`strong`,null,`Rachel Green:`,-1),c[890]||=i(` What?! Why?!`,-1),c[891]||=a(`blockquote`,null,[a(`p`,null,`什么？！为什么？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/215.mp3`}),c[892]||=i(),c[893]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[894]||=i(` Well because you didn't give me advice! No! You gave me a pickup line! As soon as I told her I wanted to y'know, build a foundation and be friends first. I suddenly, through no fault of my own, became irresistible to her! (Pause) And her roommate!`,-1),c[895]||=a(`blockquote`,null,[a(`p`,null,`因为你没有给我建议！不你给我接电话了！一旦我告诉她我想知道，建立一个基金会，首先是朋友。我突然，不是因为我自己的过错，变得对她无法抗拒！（停顿）还有她的室友！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/216.mp3`}),c[896]||=i(),c[897]||=a(`strong`,null,`Monica Geller:`,-1),c[898]||=i(` What about the closeness?`,-1),c[899]||=a(`blockquote`,null,[a(`p`,null,`那么亲密度呢？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/217.mp3`}),c[900]||=i(),c[901]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[902]||=i(` Closeness-shmoshness! There was three of us for crying out loud!`,-1),c[903]||=a(`blockquote`,null,[a(`p`,null,`亲密，羞涩！我们中有三个人大声喊叫！`)],-1),c[904]||=a(`hr`,null,null,-1),c[905]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, Joey is entering with a pizza and finds everyone but Ross there.`)],-1),c[906]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，乔伊拿着一个比萨饼进来，发现除了罗斯以外所有人都在那里。`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/218.mp3`}),c[907]||=i(),c[908]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[909]||=i(` (entering) All right! Hey, who wants pizza?!`,-1),c[910]||=a(`blockquote`,null,[a(`p`,null,`（进来）好吧！嘿，谁要比萨饼？！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/219.mp3`}),c[911]||=i(),c[912]||=a(`strong`,null,`Chandler Bing:`,-1),c[913]||=i(` Ooh, I do! I do! I do!`,-1),c[914]||=a(`blockquote`,null,[a(`p`,null,`哦，是的！我愿意！我愿意！`)],-1),c[915]||=a(`p`,null,[a(`em`,null,`(They all walk over to get a slice.)`)],-1),c[916]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们都走过去吃一片。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/220.mp3`}),c[917]||=i(),c[918]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[919]||=i(` (taking a bite) Oh, great! Can you believe I found it on the second floor?`,-1),c[920]||=a(`blockquote`,null,[a(`p`,null,`（咬了一口）哦，太好了！你相信我在二楼找到的吗？`)],-1),c[921]||=a(`p`,null,[a(`em`,null,`(They all throw their pieces back as there is a knock on the door.)`)],-1),c[922]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（有人敲门，他们都把自己的东西扔了回去。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/221.mp3`}),c[923]||=i(),c[924]||=a(`strong`,null,`Monica Geller:`,-1),c[925]||=i(` Who is it?`,-1),c[926]||=a(`blockquote`,null,[a(`p`,null,`是谁？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/222.mp3`}),c[927]||=i(),c[928]||=a(`strong`,null,`Voice:`,-1),c[929]||=i(` N.Y.P.D!!`,-1),c[930]||=a(`blockquote`,null,[a(`p`,null,`纽约警察局！！`)],-1),c[931]||=a(`p`,null,`Phoebe and **Joey Tribbiani: **Oh my God!`,-1),c[932]||=a(`blockquote`,null,[a(`p`,null,[i(`菲比和`),a(`strong`,null,`乔伊·崔比安尼：`),i(`我的天啊！`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/223.mp3`}),c[933]||=i(),c[934]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[935]||=i(` Uhh, just a minute officer!!`,-1),c[936]||=a(`blockquote`,null,[a(`p`,null,`哦，等一下，警官！！`)],-1),c[937]||=a(`p`,null,[a(`em`,null,`(He throws his piece back in the box, runs into the living room, looks for a place to hide the pizza, finds one, slides the box under the couch, sits down on the table, and tries to quickly chew the food in his mouth.)`)],-1),c[938]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他把自己的比萨饼扔回盒子，跑进起居室，找个地方藏比萨饼，找到了一个，把盒子滑到沙发下面，坐在桌子上，试着快速咀嚼嘴里的食物。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/224.mp3`}),c[939]||=i(),c[940]||=a(`strong`,null,`Cop:`,-1),c[941]||=i(` I'm looking for Phoebe Buffay!`,-1),c[942]||=a(`blockquote`,null,[a(`p`,null,`我在找菲比·布菲！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/225.mp3`}),c[943]||=i(),c[944]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[945]||=i(` Ooh, God, it's him! It's that cop! God, I can't believe it! He found me!`,-1),c[946]||=a(`blockquote`,null,[a(`p`,null,`哦，上帝，是他！是那个警察！天哪，我简直不敢相信！他找到我了！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/226.mp3`}),c[947]||=i(),c[948]||=a(`strong`,null,`Rachel Green:`,-1),c[949]||=i(` Oh my God, Phoebe, are you gonna go to jail?!`,-1),c[950]||=a(`blockquote`,null,[a(`p`,null,`哦，天哪，菲比，你要坐牢吗？！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/227.mp3`}),c[951]||=i(),c[952]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[953]||=i(` Well, if I'm going down, I'm taking you (Points at all of them) with me. (They all look at her.) Harboring a fugitive? That's one to three years minimum. Good luck Chandler. (She opens the door to the cop from before.) Okay, you can arrest me. Fine. But you'll never make it stick and you know it!`,-1),c[954]||=a(`blockquote`,null,[a(`p`,null,`好吧，如果我要倒下，我会带着你（所有的分数）一起走。（他们都看着她）窝藏逃犯？那至少是一到三年。祝你好运，钱德勒。（她从前面向警察开门）好的，你可以逮捕我。好的但你永远也无法坚持下去，你知道的！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/228.mp3`}),c[955]||=i(),c[956]||=a(`strong`,null,`Cop:`,-1),c[957]||=i(` Yeah, but I kinda don't have a choice, it's my job. I mean, you understand right?`,-1),c[958]||=a(`blockquote`,null,[a(`p`,null,`是的，但我别无选择，这是我的工作。我是说，你明白吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/229.mp3`}),c[959]||=i(),c[960]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[961]||=i(` Yep! As long as you understand that I'm going to call my lawyer and once he puts you on the stand he'll make you look like a fool. A fool!`,-1),c[962]||=a(`blockquote`,null,[a(`p`,null,`是的！只要你明白我会打电话给我的律师，一旦他让你出庭，他会让你看起来像个傻瓜。傻瓜！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/230.mp3`}),c[963]||=i(),c[964]||=a(`strong`,null,`Cop:`,-1),c[965]||=i(` I don't like looking foolish. Y'know what? Maybe uh, I don't arrest you today. Maybe I came by and you weren't here.`,-1),c[966]||=a(`blockquote`,null,[a(`p`,null,`我不喜欢看起来很傻。你知道吗？也许，我今天不逮捕你。也许我路过而你不在这里。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/231.mp3`}),c[967]||=i(),c[968]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[969]||=i(` I would love it if I weren't here!`,-1),c[970]||=a(`blockquote`,null,[a(`p`,null,`如果我不在这里，我会喜欢的！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/232.mp3`}),c[971]||=i(),c[972]||=a(`strong`,null,`Cop:`,-1),c[973]||=i(` Okay, so since umm, you're not going to jail tonight I was wondering if you would like to go to dinner with me?`,-1),c[974]||=a(`blockquote`,null,[a(`p`,null,`好吧，既然你今晚不进监狱，我想知道你是否愿意和我一起去吃饭？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/233.mp3`}),c[975]||=i(),c[976]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[977]||=i(` Me?!`,-1),c[978]||=a(`blockquote`,null,[a(`p`,null,`我？！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/234.mp3`}),c[979]||=i(),c[980]||=a(`strong`,null,`Cop:`,-1),c[981]||=i(` Yeah. Ever since you flashed my badge at me, I kinda can't stop thinking about you. You're the prettiest, fake undercover whore I've ever seen.`,-1),c[982]||=a(`blockquote`,null,[a(`p`,null,`是的。自从你向我亮出我的徽章，我就一直在想你。你是我见过的最漂亮的假卧底妓女。`)],-1),c[983]||=a(`p`,null,`Chandler and **Joey Tribbiani: **Nice!`,-1),c[984]||=a(`blockquote`,null,[a(`p`,null,[i(`钱德勒和`),a(`strong`,null,`乔伊·崔比安尼：`),i(`很好！`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/235.mp3`}),c[985]||=i(),c[986]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[987]||=i(` Wow! I didn't see that coming! You're-you're asking me out!`,-1),c[988]||=a(`blockquote`,null,[a(`p`,null,`哇！我没想到会这样！你在约我出去！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/236.mp3`}),c[989]||=i(),c[990]||=a(`strong`,null,`Cop:`,-1),c[991]||=i(` Yeah. I mean, I coulda done it better, but these people keep staring at me.`,-1),c[992]||=a(`blockquote`,null,[a(`p`,null,`是的。我是说，我本可以做得更好，但这些人一直盯着我看。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/237.mp3`}),c[993]||=i(),c[994]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[995]||=i(` Umm, yeah, I'd like to go out with you officer…`,-1),c[996]||=a(`blockquote`,null,[a(`p`,null,`嗯，是的，我想和你出去，警官…`)],-1),r(p,{src:`/audio/friends/S05/S05E16/238.mp3`}),c[997]||=i(),c[998]||=a(`strong`,null,`Cop:`,-1),c[999]||=i(` Gary.`,-1),c[1e3]||=a(`blockquote`,null,[a(`p`,null,`加里。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/239.mp3`}),c[1001]||=i(),c[1002]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1003]||=i(` Gary.`,-1),c[1004]||=a(`blockquote`,null,[a(`p`,null,`加里。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/240.mp3`}),c[1005]||=i(),c[1006]||=a(`strong`,null,`Gary:`,-1),c[1007]||=i(` Okay, so it's a date.`,-1),c[1008]||=a(`blockquote`,null,[a(`p`,null,`好吧，那就是约会了。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/241.mp3`}),c[1009]||=i(),c[1010]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1011]||=i(` Yeah! So--ooh, I gotta ask you though. How did you know where to find me?`,-1),c[1012]||=a(`blockquote`,null,[a(`p`,null,`是啊！所以，我得问问你。你怎么知道我在哪里？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/242.mp3`}),c[1013]||=i(),c[1014]||=a(`strong`,null,`Gary:`,-1),c[1015]||=i(` Well you're fingerprints were all over my badge so I just ran it through the computer and this was listed as your last known address so I just checked it out.`,-1),c[1016]||=a(`blockquote`,null,[a(`p`,null,`嗯，我的徽章上到处都是你的指纹，所以我只是在电脑里查了一下，这是你最后知道的地址，所以我才查了出来。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/243.mp3`}),c[1017]||=i(),c[1018]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1019]||=i(` Ohh, impressive.`,-1),c[1020]||=a(`blockquote`,null,[a(`p`,null,`哦，太棒了。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/244.mp3`}),c[1021]||=i(),c[1022]||=a(`strong`,null,`Gary:`,-1),c[1023]||=i(` Not as impressive as you. I gotta tell you, I looked at your record and you've done some pretty weird stuff.`,-1),c[1024]||=a(`blockquote`,null,[a(`p`,null,`没有你那么令人印象深刻。我得告诉你，我看了你的唱片，你做了一些很奇怪的事情。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/245.mp3`}),c[1025]||=i(),c[1026]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1027]||=i(` Yeah, we'll talk at dinner.`,-1),c[1028]||=a(`blockquote`,null,[a(`p`,null,`是的，我们晚餐时再谈。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/246.mp3`}),c[1029]||=i(),c[1030]||=a(`strong`,null,`Gary:`,-1),c[1031]||=i(` Okay. (He starts to leave.) So I'll come by in a couple hours and pick you up?`,-1),c[1032]||=a(`blockquote`,null,[a(`p`,null,`好的。（他开始离开。）那么我几个小时后过来接你？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/247.mp3`}),c[1033]||=i(),c[1034]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1035]||=i(` All right, I can't wait!`,-1),c[1036]||=a(`blockquote`,null,[a(`p`,null,`好吧，我等不及了！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/248.mp3`}),c[1037]||=i(),c[1038]||=a(`strong`,null,`Gary:`,-1),c[1039]||=i(` Okay. And don't worry, I'm not just gonna take you out for donuts.`,-1),c[1040]||=a(`blockquote`,null,[a(`p`,null,`好的。别担心，我不会带你出去吃甜甜圈的。`)],-1),c[1041]||=a(`p`,null,[a(`em`,null,`(Chandler busts out laughing and everyone just looks at him.)`)],-1),c[1042]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（钱德勒突然大笑起来，每个人都看着他。）`)])],-1),r(p,{src:`/audio/friends/S05/S05E16/249.mp3`}),c[1043]||=t(` <strong>Chandler Bing:</strong> (To Rachel) He has a gun!<blockquote><p>（对瑞秋）他有枪！</p></blockquote><p>Closing Credits</p><blockquote><p>片尾字幕</p></blockquote><hr><p>🎬 <em>The couch store, Ross is talking to a saleswoman.</em></p><blockquote><p>🎬 <em>沙发店，罗斯正在和一位女售货员谈话。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S05/S05E16/250.mp3`}),c[1044]||=i(),c[1045]||=a(`strong`,null,`Ross Geller:`,-1),c[1046]||=i(` I'd like to return this couch. I'm not satisfied with it.`,-1),c[1047]||=a(`blockquote`,null,[a(`p`,null,`我想还这张沙发。我对它不满意。`)],-1),c[1048]||=a(`p`,null,`[The camera cuts to show the couch, which has been cut in half.]`,-1),c[1049]||=a(`blockquote`,null,[a(`p`,null,`[摄像机切到沙发上，沙发被切成两半。]`)],-1),r(p,{src:`/audio/friends/S05/S05E16/251.mp3`}),c[1050]||=i(),c[1051]||=a(`strong`,null,`The Saleswoman:`,-1),c[1052]||=i(` You wanna return this couch? (Ross nods yes.) It's cut in half!`,-1),c[1053]||=a(`blockquote`,null,[a(`p`,null,`你想还这张沙发吗？（罗斯点头同意。）它被切成两半了！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/252.mp3`}),c[1054]||=i(),c[1055]||=a(`strong`,null,`Ross Geller:`,-1),c[1056]||=i(` That's what I'm telling you.`,-1),c[1057]||=a(`blockquote`,null,[a(`p`,null,`这就是我要告诉你的。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/253.mp3`}),c[1058]||=i(),c[1059]||=a(`strong`,null,`The Saleswoman:`,-1),c[1060]||=i(` Did you cut this couch in half?`,-1),c[1061]||=a(`blockquote`,null,[a(`p`,null,`你把这张沙发切成两半了吗？`)],-1),r(p,{src:`/audio/friends/S05/S05E16/254.mp3`}),c[1062]||=i(),c[1063]||=a(`strong`,null,`Ross Geller:`,-1),c[1064]||=i(` This couch, is cut in half! I would like to exchange it for one that is not cut in half!`,-1),c[1065]||=a(`blockquote`,null,[a(`p`,null,`这张沙发，被切成两半了！我想把它换成一个不是切成两半的！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/255.mp3`}),c[1066]||=i(),c[1067]||=a(`strong`,null,`The Saleswoman:`,-1),c[1068]||=i(` You're telling me this couch was delivered to you like this?!`,-1),c[1069]||=a(`blockquote`,null,[a(`p`,null,`你是说这张沙发是这样送给你的？！`)],-1),r(p,{src:`/audio/friends/S05/S05E16/256.mp3`}),c[1070]||=i(),c[1071]||=a(`strong`,null,`Ross Geller:`,-1),c[1072]||=i(` Look, I am a reasonable man. I will accept store credit.`,-1),c[1073]||=a(`blockquote`,null,[a(`p`,null,`听着，我是个通情达理的人。我接受商店赊帐。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/257.mp3`}),c[1074]||=i(),c[1075]||=a(`strong`,null,`The Saleswoman:`,-1),c[1076]||=i(` I'll give you store credit in the amount of four dollars.`,-1),c[1077]||=a(`blockquote`,null,[a(`p`,null,`我给你四美元的商店赊账。`)],-1),r(p,{src:`/audio/friends/S05/S05E16/258.mp3`}),c[1078]||=i(),c[1079]||=a(`strong`,null,`Ross Geller:`,-1),c[1080]||=i(` (thinks) I take it.`,-1),c[1081]||=a(`blockquote`,null,[a(`p`,null,`（想）我接受了。`)],-1),c[1082]||=a(`p`,null,`contrl08.gif (14783 bytes)`,-1),c[1083]||=a(`blockquote`,null,[a(`p`,null,`contrl08.gif（14783字节）`)],-1)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};